            if (입력틀[번호] != 255) 방송 = false;
        }
        if (!자기 && !방송) return;
        if (수16(입력틀, 12) == 0x0806) { 주소처리(길이); return; }
        if (수16(입력틀, 12) != 0x0800) return;
        if (길이 < 34 || (입력틀[14] >>> 4) != 4) { 폐기수++; return; }
        int 머리길이 = (입력틀[14] & 15) * 4, 전체길이 = 수16(입력틀, 16);
        if (머리길이 < 20 || 머리길이 > 60 || 전체길이 < 머리길이 + 8 || 전체길이 > 길이 - 14
            || (수16(입력틀, 20) & 0x3fff) != 0 || 입력틀[23] != 17
            || 수32(입력틀, 30) != 내주소 || 합(입력틀, 14, 머리길이, 0) != 65535) { 폐기수++; return; }
        int 시작 = 14 + 머리길이, 자료길이 = 수16(입력틀, 시작 + 4);
        if (자료길이 < 8 || 자료길이 != 전체길이 - 머리길이 || 자료길이 > 1032) { 폐기수++; return; }
        int 출발 = 수32(입력틀, 26);
        if (수16(입력틀, 시작 + 6) != 0 && 합(입력틀, 시작, 자료길이, 가상머리합(출발, 내주소, 자료길이)) != 65535) {
            폐기수++; return;
        }
        int 목적 = 수16(입력틀, 시작 + 2);
        for (int 칸 = 0; 칸 < 4; 칸++) if (접속번호들[칸] != 0 && 접속번호들[칸] == 목적) {
            if (받은길이[칸] >= 0) { 폐기수++; return; }
            받은길이[칸] = 자료길이 - 8; 받은주소[칸] = 출발; 받은접속번호[칸] = 수16(입력틀, 시작);
            for (int 번호 = 0; 번호 < 자료길이 - 8; 번호++) 받은자료[칸 * 1024 + 번호] = 입력틀[시작 + 8 + 번호];
