        }
    }

    static void 확인() {
        for (int 번호 = 0; 번호 < 16; 번호++) {
            int 길이 = 망장치구동기.받기(입력틀);
            if (길이 == 0) return;
            틀처리(길이);
        }
    }
    static int 주소찾기(int 주소) {
