            확인();
            if (찾은주소 == 다음) return 0;
            장치.잠시양보();
        }
        return -110;
    }
    static int 보내기(int 손잡이, int 주소, int 접속번호, int[] 자료, int 길이) {
        int 칸 = 번호(손잡이);
        if (칸 < 0) return -9;
        if (망장치구동기.입출력기준주소 == 0) return -19;
        if (접속번호 < 1 || 접속번호 > 65535 || 길이 < 0 || 길이 > 1024) return -22;
        int 결과 = 주소찾기(주소);
        if (결과 < 0) return 결과;
        바깥머리(0x0800, false);
        출력틀[14] = 0x45; 출력틀[15] = 0; 넣기16(출력틀, 16, 28 + 길이);
        넣기16(출력틀, 18, 식별자++); 넣기16(출력틀, 20, 0x4000);
        출력틀[22] = 64; 출력틀[23] = 17; 넣기16(출력틀, 24, 0);
        넣기32(출력틀, 26, 내주소); 넣기32(출력틀, 30, 주소);
        넣기16(출력틀, 24, ~합(출력틀, 14, 20, 0));
        넣기16(출력틀, 34, 접속번호들[칸]); 넣기16(출력틀, 36, 접속번호);
        넣기16(출력틀, 38, 길이 + 8); 넣기16(출력틀, 40, 0);
        for (int 번호 = 0; 번호 < 길이; 번호++) 출력틀[42 + 번호] = 자료[번호] & 255;
