        넣기16(출력틀, 40, 검사합 == 0 ? 65535 : 검사합);
        결과 = 망장치구동기.보내기(출력틀, 길이 + 42);
        return 결과 < 0 ? 결과 : 길이;
    }
    static int 받기(int 손잡이, int[] 자료, int 용량, int 제한) {
        int 칸 = 번호(손잡이);
        if (칸 < 0) return -9;
        int 시작 = 장치.밀리초();
        while (true) {
            확인();
            int 길이 = 받은길이[칸];
            if (길이 >= 0) {
                받은길이[칸] = -1;
                if (길이 > 용량) return -90;
                for (int 번호 = 0; 번호 < 길이; 번호++) 자료[번호] = 받은자료[칸 * 1024 + 번호];
                return 길이;
            }
            if (제한 == 0) return -11;
            if (장치.밀리초() - 시작 >= 제한) return -110;
            장치.잠시양보();
        }
    }
    static void 상태() {
        문자단말.쓰기(망장치구동기.입출력기준주소 == 0 ? "NET unavailable (RTL8139 required)\n" : "NET RTL8139 10.0.2.15/24 gateway 10.0.2.2 UDP\n");
        문자단말.쓰기("TX: "); 문자단말.수쓰기(망장치구동기.송신수);
        문자단말.쓰기(" RX: "); 문자단말.수쓰기(망장치구동기.수신수);
        문자단말.쓰기(" DROP: "); 문자단말.수쓰기(폐기수);
        문자단말.쓰기("\n");
    }
}

