import java.util.Arrays;

/** 실제 Java 규약 처리기를 JVM에서 호출해 경계와 손상된 입력을 빠르게 검사한다. */
public final class 패킷시험 {
    static int 횟수 = 0;
    static void 확인(boolean 값) { if (!값) throw new AssertionError("case " + 횟수); 횟수++; }
    static int 검사합(int[] 값, int 시작, int 길이, int 초기) {
        int 합 = 초기;
        for (int 번호 = 0; 번호 < 길이; 번호++) 합 += 값[시작 + 번호] << ((번호 & 1) == 0 ? 8 : 0);
        합 = (합 & 65535) + (합 >>> 16);
        합 = (합 & 65535) + (합 >>> 16);
        return ~합 & 65535;
    }
    static void 준비(int 길이) {
        통신망.과정정리();
        확인(통신망.열기(5000) == 3);
        int[] 틀 = 통신망.입력틀;
