        통신망.넣기16(틀, 34, 4321); 통신망.넣기16(틀, 36, 5000); 통신망.넣기16(틀, 38, 길이 + 8);
        for (int 번호 = 0; 번호 < 길이; 번호++) 틀[42 + 번호] = 번호 & 255;
        검사합넣기(길이);
    }
