        int 합 = 검사합(틀, 34, 길이 + 8, 초기);
        통신망.넣기16(틀, 40, 합 == 0 ? 65535 : 합);
    }
    static void 거부(int 길이) { 통신망.틀처리(길이); 확인(통신망.받은길이[0] == -1); }
    public static void main(String[] 인수) {
