            for (int 번호 = 0; 번호 < 길이; 번호++) 확인(통신망.받은자료[번호] == (번호 & 255));
        }
        for (int 길이 = 0; 길이 < 42; 길이++) { 준비(0); 거부(길이); }
        준비(1025); 거부(1067);
        준비(2); 통신망.입력틀[24] ^= 1; 거부(44);
        준비(2); 통신망.입력틀[42] ^= 1; 거부(44);
        준비(2); 통신망.넣기16(통신망.입력틀, 38, 7); 거부(44);
