        확인(검사합(보냄, 14, 20, 0) == 0);
        확인(검사합(보냄, 34, 11, 통신망.가상머리합(통신망.내주소, 통신망.관문, 11)) == 0);
        확인(보냄[42] == 1 && 보냄[44] == 3);
